from pathlib import Path
import textwrap


template = (
    textwrap.dedent(
        """\
        # --------------------------------------------------
        # Studio Vault .gitignore
        # Generated by: wkb create-vault
        # Purpose: keep editorial content under version control
        # while ignoring runtime/editor/pipeline noise
        # --------------------------------------------------


        # --------------------------------------------------
        # OS junk
        # --------------------------------------------------

        .DS_Store
        Thumbs.db


        # --------------------------------------------------
        # Editor temporary files
        # --------------------------------------------------

        *~
        *.swp
        *.swo


        # --------------------------------------------------
        # Obsidian runtime state (machine-specific)
        # --------------------------------------------------

        .obsidian/workspace*
        .obsidian/workspace.json
        .obsidian/cache/


        # --------------------------------------------------
        # Plugin runtime data
        # (safe to regenerate)
        # --------------------------------------------------

        .obsidian/plugins/*/data.json


        # --------------------------------------------------
        # AutoScribe / Workbench staging
        # --------------------------------------------------

        _ingest/
        _staging/
        _tmp/


        # --------------------------------------------------
        # Pipeline intermediates
        # --------------------------------------------------

        *.ndjson
        *.ndjsonl


        # --------------------------------------------------
        # Logs
        # --------------------------------------------------

        *.log


        # --------------------------------------------------
        # Python runtime debris (rare but possible)
        # --------------------------------------------------

        __pycache__/
        *.pyc
        """
    ).rstrip()
    + "\n"
)




def write_gitignore(folder: Path) -> Path:
    """Write the standard vault .gitignore into folder and return its path."""
    target = folder.expanduser().resolve() / ".gitignore"
    target.write_text(template, encoding="utf-8")
    return target